/* From Uiverse.io by MikeAndrewDesigner - Tags: checkbox, rounded, clean */
.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: block;
  position: relative;
  cursor: pointer;
  font-size: 30px;
  user-select: none;
}

.__UIV_SCOPE__ .checkmark {
  position: relative;
  top: 0;
  left: 0;
  height: 1.6em;
  width: 1.6em;
  border-radius: 50%;
  background: #ffeded38;
  transition: all 0.2s ease;
}

.__UIV_SCOPE__ .checkmark {
  opacity: 0.4;
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark {
  background: linear-gradient(144deg,#af40ff,#5b42f3 50%,#00ddeb);
  opacity: 0.9;
  transition: all 0.2s ease;
}

.__UIV_SCOPE__ .checkmark:after {
  content: "";
  position: absolute;
  display: none;
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark:after {
  display: block;
}

.__UIV_SCOPE__ .container .checkmark:after {
  left: 0.61em;
  top: 0.43em;
  width: 0.25em;
  height: 0.5em;
  border: solid rgb(255, 255, 255);
  border-width: 0 0.15em 0.15em 0;
  transform: rotate(45deg);
}
